if (document.body && document.body.insertAdjacentHTML) document.body.insertAdjacentHTML('beforeend', BF_SPRITE);

/* сценарии презентации: каждый вид на этаже с главным врагом, пять на пять */
for (const [v, n, d] of [
  ['square', 'Бой · карты-квадраты', 'Вид карт «квадрат» — по умолчанию: карта 1 : 1 в прежней расстановке колонками, портрет срезом по лицу, главный враг крупнее. Элита биома, пять на пять'],
  ['portrait', 'Бой · карты-портреты', 'Вид карт «портрет»: карта — портрет целиком, 4 : 5; два ряда, главный враг крупнее. Элита биома, пять на пять'],
  ['old', 'Бой · прежние карты', 'Прежний вид: кадр 5 : 4 в рамке-картинке — лицо местами обрезано. Элита биома, пять на пять'],
]) FLOWS.push([n, d, () => {
  S.overlay = null; bfView(v);
  const sq5 = S.squads.find(q => q.m.filter(Boolean).length >= 5 && q.m.filter(Boolean).every(id => !runOf(id) && !(H(id) || {}).busy)) || S.squads[0];
  startRun(sq5.id, 'b3', 30);
}]);

/* ================== UI-кит: вид карт — прежний, портрет, квадрат ==================
   Одна сцена в трёх видах — бой ядра на отряде I, этаж с главным врагом, на 932 × 430 и 844 × 390. Карты — тот же cardHtml, что в бою;
   бой не идёт, эффекты, цели, контроль, щит и шансы вписаны так, как их рисует paintCards. Ниже — рамки квадрата и портрета по
   лестнице, состояния карты и срез портретов: у кого лицо выше всех и ниже всех */
const BF_KIT = { biome: 'b3', floor: 30, z: .68, faces: 6 };   // сцена: биом и этаж с главным врагом (элита — изучена с начала); масштаб; лиц в срезе с каждого края
function bfKitBattle() {
  const B = EB.BIOMES[BF_KIT.biome] ? BF_KIT.biome : 'b1', fl = Math.min(BF_KIT.floor, EB.BIOMES[B].floors.length);
  const b = EB.floorBattle(S.heroes.slice(0, 5).map(h => EB.heroSrc(h)), B, fl, null, 'rounds');
  const R = { b, disp: {}, biome: B, aim: {} }, [hs, fs] = b.u, st = (u, x) => { if (u) u.st.push(x); };
  /* мгновение боя: щит и бафф у танка, урон со временем и лечение, цель ×2, павший, контроль; у врагов — дебаффы, цель ×3, лёд */
  if (hs[0]) { R.disp[dkey(hs[0])] = { hp: Math.floor(hs[0].maxHp * 3 / 4), sh: Math.floor(hs[0].maxHp / 5), dead: false }; st(hs[0], { k: 'guard', left: 2, left0: 3, pow: 2500 }); }
  st(hs[1], { k: 'dot', school: 'Огонь', per: 60, stacks: 2, left: 2, left0: 3 }); st(hs[1], { k: 'hot', school: 'Вода', per: 40, stacks: 1, left: 1, left0: 2 });
  if (hs[2]) R.aim[dkey(hs[2])] = 2;
  if (hs[3]) R.disp[dkey(hs[3])] = { hp: 0, sh: 0, dead: true };
  st(hs[4], { k: 'stun', left: 1, left0: 1 });
  if (fs[0]) { R.disp[dkey(fs[0])] = { hp: Math.floor(fs[0].maxHp * 2 / 3), sh: 0, dead: false }; R.aim[dkey(fs[0])] = 3; st(fs[0], { k: 'weak', left: 2, left0: 2, pow: 2000 }); st(fs[0], { k: 'mark', left: 1, left0: 2, pow: 1500 }); }
  st(fs[1], { k: 'freeze', left: 1, left0: 2 });
  st(fs[2], { k: 'dot', school: 'Огонь', per: 60, stacks: 3, left: 2, left0: 3 });
  R.fired = fs[3] ? dkey(fs[3]) : null;
  return R;
}
/* карта сцены: разметка cardHtml без id и действия, эффекты и знаки — как после paintCards */
function bfKitPaint(h, R, u) {
  const d = R.disp[dkey(u)] || { hp: u.hp, sh: u.sh, dead: !u.alive }, [good, bad] = d.dead ? ['', ''] : statusHtml(u, d, true);
  const ctl = !d.dead && u.st.find(x => CTL.includes(x.k)), aim = d.dead ? 0 : R.aim[dkey(u)] || 0;
  const add = [aim ? 'aimed' : '', aim > 1 ? 'many' : '', ctl ? 'ctl-on' : '', ctl && ctl.k === 'stun' ? 'ctl-stun' : '', d.sh > 0 && !d.dead ? 'shielded' : '', d.dead ? 'dead' : ''].filter(Boolean).join(' ');
  const fired = R.fired === dkey(u) && u.table && u.table[0] ? u.table[0].n : null;
  return h.replace(/ id="bc\d+"/, '').replace(/ data-a="insp" data-v="[^"]*"/, '').replace('<div class="bc ', `<div class="bc ${add} `)
    .replace('<div class="buffs"></div>', `<div class="buffs">${good}</div>`).replace('<div class="debuffs"></div>', `<div class="debuffs">${bad}</div>`)
    .replace('<span class="tgt"></span>', `<span class="tgt">${aim > 1 ? '×' + aim : ''}</span>`)
    .replace('<span class="ctl"></span>', `<span class="ctl">${ctl ? ic(ST_ICON[ctl.k][0]) : ''}</span>`)
    .replace('<div class="rot"></div>', `<div class="rot">${d.dead ? '' : chanceHtml(u, fired)}</div>`);
}
/* сцена одного вида: поле боя с картами и лентой, без шапки; размер — экран прототипа без шахты и шапки, масштаб — BF_KIT.z */
function bfKitStage(R0, v, sm) {
  const R = Object.assign({}, R0, { bfv: v }), b = R.b, side = sd => b.u[sd].map((u, k) => bfKitPaint(cardHtml(R, u, b.u[sd].length, k), R, u)).join('');
  const lead = b.u[1][0], h0 = b.u[0][0], tb = h0 && h0.table && h0.table[0];
  const feed = [`<b>${b.u[1][1] ? b.u[1][1].name : lead.name}</b> · обычная атака → ${b.u[0][2] ? b.u[0][2].name : h0.name}`,
    `<b>${h0.name}</b> · <span class="gd">${tb ? tb.n : 'обычная атака'}</span>${tb ? ' · ' + pctBp(tb.ch) : ''} → ${lead.name}`,
    `<b>${lead.name}</b> · <span class="gd">${lead.table && lead.table[0] ? lead.table[0].n : 'обычная атака'}</span> → ${h0.name}`].map(x => `<p>${x}</p>`).join('');
  return `<div class="bf-sco" style="--sw:${sm ? 772 : 854}px;--sh:${sm ? 346 : 384}px;--z:${BF_KIT.z}"><div class="bf-scw"><div class="bt${bfBtCls(R)} bf-stg">
    <div class="bt-bgs"><img class="bg" src="${biomeArena(R.biome)}" alt=""></div>
    <div class="bt-field"><div class="bt-side h">${side(0)}</div><div class="bt-side f">${side(1)}</div><div class="bt-feed">${feed}</div></div>
    <span class="bf-stl">${BF_VIEW.names[v]} · ${sm ? '844 × 390' : '932 × 430'}</span></div></div></div>`;
}
/* срез портретов: лица выше всех и ниже всех — квадрат, как в бою, контур лица по BF_FACES */
function bfKitFaces() {
  const all = [];
  for (const [dir, map] of Object.entries(BF_FACES)) for (const [id, f] of Object.entries(map)) all.push([dir, id, f]);
  all.sort((a, b) => a[2][0] - b[2][0] || (a[0] + a[1]).localeCompare(b[0] + b[1]));
  const pick = all.slice(0, BF_KIT.faces).concat(all.slice(-BF_KIT.faces));
  const [w, h] = BF_SQ.img;
  return `<div class="k-demo bf-faces">${pick.map(([dir, id, f]) => {
    const y = bfCrop(f) * (h - w) / 1000, fh = (f[1] - f[0]) * h / 1000, hw = fh * 3 / 8, pc = v => (v * 100 / w).toFixed(1) + "%";   // полуширина лица — 3/8 его высоты
    return `<figure><span class="bf-fc" style="--fy:${bfCrop(f)}"><img src="${AV(dir + '/' + id + '.jpg')}" alt="" decoding="async"><i style="left:${pc(f[2] * w / 1000 - hw)};top:${pc(f[0] * h / 1000 - y)};width:${pc(2 * hw)};height:${pc(fh)}"></i></span><figcaption><b>${dir}/${id}</b><small>макушка ${f[0]} ‰ · срез ${bfCrop(f)} ‰</small></figcaption></figure>`;
  }).join('')}</div>`;
}
KIT_EXTRA.push({
  html: () => {
    const R = bfKitBattle(), keys = Object.keys(BF.types);
    const pair = list => `<div class="bf-cmp">${list.map(([v, sm]) => bfKitStage(R, v, sm)).join('')}</div>`;
    const row = (o, list) => `<div class="k-demo bf-kit">${list.map(([t, cap, sub, st]) => `<figure>${bfKitCard(t, Object.assign({ st }, o))}<figcaption><b>${cap}</b><small>${bfEsc(sub)}</small></figcaption></figure>`).join('')}</div>`;
    const frames = keys.map(t => [t, t === 'hero' ? 'Герой' : BF.types[t].n, BF.types[t].where, '']);
    const states = [['hero', 'Обычная', 'эффекты — столбиком по краям', ''], ['hero', 'Цель ×2', 'красная рамка и «×N»', 'aim'], ['o', 'Контроль', 'знак — на верхней планке', 'ctl'],
      ['hero', 'Щит', 'кольцо щита, полоса щита — поверх здоровья', 'sh'], ['e', 'Не изучен', 'портрет скрыт до первой победы', 'unk'], ['hero', 'Пал', 'надпись — не на лице', 'dead'], ['b', 'Выбрана', 'нажатие — карточка бойца', 'sel'], ['hero', 'Много эффектов', 'столбиком, лишние — к середине', 'fx4']];
    const P = BF_SQ.size, L = BF_SQ.lead;
    return `<section class="k-box" style="grid-column:1/-1"><h3>Карты боя · вид: прежний, портрет и квадрат</h3>
      <p class="k-note">Слова автора 01.10.2026: карты — не обрезанные, как нарисован портрет; посмотрев оба вида — «сойтись на квадратах и для героев, и для врагов». Квадрат — вид по умолчанию: карта 1 : 1 в прежней расстановке колонками. Переключатель «Вид карт» — в панели прототипа и в легенде «Знаки» для команды. Одна сцена в трёх видах — бой ядром, этаж с главным врагом.</p>
      ${pair([['old', false], ['square', false]])}${pair([['old', true], ['square', true]])}${pair([['portrait', false], ['portrait', true]])}
      <p class="k-note">Квадрат: колонки, как в прежнем виде, — у героев 2 + 3, у врагов 3 + 2. Портрет ложится срезом по лицу: у каждого портрета в данных — макушка, подбородок и середина лица (<code>BF_FACES</code>), над макушкой — запас ${BF_SQ.head / 10} % стороны. Эффекты — столбиком по краям, «×N» — на углу рамки; внизу, на теле, — имя целиком в одну-две строки, под ним шансы и знак класса; здоровье и щит — нижняя планка рамки; контроль — знак на верхней планке, «пал» — на месте шансов. Сторона портрета на 932 × 430 — ${P.lg} px, у главного врага — ${P.lg * L / 100} px; на 844 × 390 — ${P.sm} и ${(P.sm * L / 100).toFixed(1).replace('.', ',')} px. Прежний кадр — 74 × 62 и 74 × 50.</p>
      ${row({ v: 'square', sp: P.lg, hp: 72, sh: 16, fx: true }, frames)}
      <p class="k-note">Рамки квадрата, обычная карта на 932 × 430. Слева направо — лестница опасности: рядовой — голое железо и заклёпка; элита — уголёк в шипастом гнезде, уголки и свет; боссы — костяной венец с огненным глазом, бронзовые кольца с нефритом, синяя сфера Голоса, у всех — двойная кромка; рунный страж — бирюзовый кристалл с крыльями; Убер — зелёный глаз в шипах и огонь, дышит светом; Хозяин стихии — серебряный венец шипов, молнии и рога; вершина — Забытый (сломанная золотая корона в цепях между камнями) и Многоликий (венец из семи масок, золотой свет): тройная кромка и самый сильный свет. Герой — бронза, кристалл редкости в гнезде, звёзды доблести по верхней планке. Рамка — CSS и векторные украшения (<code>BF_SPRITE</code>); задания на нарисованные — <code>tools/art-gen/jobs/battle-frames-square.json</code>.</p>
      ${row({ v: 'square', sp: P.lg, hp: 58, sh: 0, fx: true }, states)}
      <p class="k-note">Состояния карты-квадрата — как в бою: ничто не ложится на лицо.</p>
      ${row({ v: 'portrait', pw: 84, hp: 72, sh: 16, fx: true }, frames)}
      ${row({ v: 'portrait', pw: 84, hp: 58, sh: 0, fx: true }, states)}
      <p class="k-note">Портрет: карта — портрет целиком, 464 × 576; два ряда — три карты сверху, две снизу со смещением; главный враг в 1,3 раза крупнее, у края к героям; здоровье, имя и шансы — под рамкой. Задания на нарисованные — <code>tools/art-gen/jobs/battle-frames-portrait.json</code>.</p>
      ${bfKitFaces()}
      <p class="k-note">Срез портретов: слева — у кого макушка выше всех, справа — ниже всех; квадрат — как в бою, зелёный контур — лицо по данным. Карта и место — <code>bfCard</code>, <code>BF_SQ</code>, <code>BF_FACES</code> и <code>BF_VIEW</code> в <code>screens/battle-cards.js</code>, размеры — <code>screens/battle-cards.css</code>, проверка — <code>tools/content-gen/screens/check_battle_cards.js</code>.</p></section>`;
  },
});
